<script setup>
import {onMounted,ref} from 'vue'
const form=ref({provider:'local',local_path:'/app/storage/inbound-media',public_base_url:'',max_upload_mb:25,s3_endpoint_url:'',s3_region:'',s3_bucket:'',s3_access_key:'',s3_secret_key:'',s3_prefix:'',s3_use_ssl:true,s3_path_style:false}),loading=ref(true),saving=ref(false),testing=ref(false),message=ref(''),error=ref('')
async function req(path,options={}){const r=await fetch(`/api/v1/settings/media-storage${path}`,{credentials:'include',headers:{'Content-Type':'application/json'},...options});const p=await r.json().catch(()=>({}));if(!r.ok)throw new Error(typeof p.detail==='string'?p.detail:`Request failed (${r.status})`);return p}
async function load(){loading.value=true;try{Object.assign(form.value,await req(''))}catch(e){error.value=e.message}finally{loading.value=false}}
async function save(){saving.value=true;message.value='';error.value='';try{Object.assign(form.value,await req('',{method:'PUT',body:JSON.stringify(form.value)}));form.value.s3_access_key='';form.value.s3_secret_key='';message.value='Media storage settings saved.'}catch(e){error.value=e.message}finally{saving.value=false}}
async function test(){testing.value=true;message.value='';error.value='';try{const p=await req('/test',{method:'POST'});message.value=p.message}catch(e){error.value=e.message}finally{testing.value=false}}
onMounted(load)
</script>
<template><main class="storage-page"><header><p>Settings</p><h1>Media Storage</h1><span>Choose where images captured by flows are stored. Changing provider affects new uploads only; existing local media remains available.</span></header><div v-if="error" class="alert error">{{error}}</div><div v-if="message" class="alert ok">{{message}}</div><section v-if="!loading" class="card"><h2>Storage provider</h2><div class="providers"><button :class="{active:form.provider==='local'}" @click="form.provider='local'"><b>▣ Local Storage</b><span>Store media on the WA Connect server.</span></button><button :class="{active:form.provider==='s3'}" @click="form.provider='s3'"><b>☁ S3 / Compatible</b><span>AWS S3, MinIO, R2, Wasabi, Backblaze and compatible services.</span></button></div><div class="fields"><template v-if="form.provider==='local'"><label><span>Storage directory</span><input v-model="form.local_path" placeholder="/app/storage/inbound-media"><small>This path must be persistent and writable by the API container.</small></label><label><span>Public base URL</span><input v-model="form.public_base_url" placeholder="https://waconnect.example.com"><small>Leave blank to use the application public URL.</small></label></template><template v-else><label class="wide"><span>S3 endpoint URL</span><input v-model="form.s3_endpoint_url" placeholder="https://s3.amazonaws.com or https://minio.example.com"><small>Leave blank for standard AWS S3.</small></label><label><span>Region</span><input v-model="form.s3_region" placeholder="af-south-1"></label><label><span>Bucket</span><input v-model="form.s3_bucket" placeholder="wa-connect-media"></label><label><span>Access key</span><input v-model="form.s3_access_key" autocomplete="off" :placeholder="form.has_access_key?'Configured — leave blank to keep':'Access key'"></label><label><span>Secret key</span><input v-model="form.s3_secret_key" type="password" autocomplete="new-password" :placeholder="form.has_secret_key?'Configured — leave blank to keep':'Secret key'"></label><label><span>Object prefix</span><input v-model="form.s3_prefix" placeholder="wa-connect/inbound"></label><label><span>Public / CDN base URL</span><input v-model="form.public_base_url" placeholder="https://media.example.com"><small>Recommended for private/custom endpoints and CDN-backed buckets.</small></label><div class="checks wide"><label><input v-model="form.s3_use_ssl" type="checkbox"> Use SSL</label><label><input v-model="form.s3_path_style" type="checkbox"> Path-style addressing (commonly needed for MinIO)</label></div></template><label><span>Maximum image size</span><div class="suffix"><input v-model.number="form.max_upload_mb" type="number" min="1" max="250"><b>MB</b></div></label></div><footer><button class="secondary" :disabled="testing||saving" @click="test">{{testing?'Testing…':'Test Storage'}}</button><button class="primary" :disabled="saving||testing" @click="save">{{saving?'Saving…':'Save Settings'}}</button></footer></section></main></template>
<style scoped>.storage-page{margin-left:220px;padding:34px 38px;min-height:100vh;background:#f4f7f6}.storage-page header{margin-bottom:22px}.storage-page header p{margin:0;text-transform:uppercase;color:#119052;font-size:11px;font-weight:800;letter-spacing:.08em}.storage-page h1{margin:3px 0 5px;font-size:30px}.storage-page header span{color:#74867e}.card{max-width:980px;background:#fff;border:1px solid #dfe7e3;border-radius:14px;padding:22px}.card h2{margin:0 0 14px}.providers{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-bottom:22px}.providers button{text-align:left;border:1px solid #d7e2dd;background:#fff;border-radius:11px;padding:16px;cursor:pointer}.providers button.active{border-color:#19a65d;background:#effaf4;box-shadow:0 0 0 1px #19a65d inset}.providers b,.providers span{display:block}.providers span{font-size:12px;color:#71847a;margin-top:5px}.fields{display:grid;grid-template-columns:1fr 1fr;gap:15px}.fields label{display:grid;gap:6px}.fields label>span{font-size:12px;font-weight:700;color:#3e584d}.fields input{box-sizing:border-box;width:100%;border:1px solid #ccd9d3;border-radius:8px;padding:10px;background:#fff}.fields small{font-size:10px;color:#819087}.wide{grid-column:1/-1}.checks{display:flex!important;gap:22px!important;padding:10px 0}.checks label{display:flex!important;align-items:center;gap:7px!important;font-size:12px}.checks input{width:auto}.suffix{display:grid;grid-template-columns:1fr 48px}.suffix input{border-radius:8px 0 0 8px}.suffix b{display:grid;place-items:center;background:#eef4f1;border:1px solid #ccd9d3;border-left:0;border-radius:0 8px 8px 0;font-size:11px}footer{display:flex;justify-content:flex-end;gap:9px;margin-top:24px;padding-top:18px;border-top:1px solid #e7eeea}footer button{border-radius:8px;padding:10px 15px;font-weight:800;cursor:pointer}.primary{border:0;background:#13a65b;color:#fff}.secondary{border:1px solid #cbd9d2;background:#fff;color:#285142}.alert{max-width:980px;box-sizing:border-box;padding:11px 14px;border-radius:9px;margin-bottom:12px}.alert.ok{background:#eaf8f0;color:#176a43}.alert.error{background:#fff0f0;color:#9c2929}@media(max-width:900px){.providers,.fields{grid-template-columns:1fr}.wide{grid-column:auto}}</style>
